Build FR Core Patient.code:
// This adaptor has no HTTP operations yet: build the resource on state,
// then send it in a later step (e.g. with the fhir-4 or http adaptor).
fn(state => {
  state.patient = {
    resourceType: 'Patient',
    meta: { profile: ['http://hl7.fr/ig/fhir/core/StructureDefinition/fr-core-patient'] },
    identifier: [
      {
        // INS (Identifiant National de Santé), NIR-based.
        system: 'urn:oid:1.2.250.1.213.1.4.8',
        value: state.data.ins,
      },
    ],
    name: [{ use: 'official', family: state.data.nom, given: [state.data.prenom] }],
    gender: state.data.sexe === 'F' ? 'female' : 'male',
    birthDate: state.data.dateNaissance, // YYYY-MM-DD
  };
  return state;
});

Build FR Core Practitioner.code:
// Build a Practitioner identified by their RPPS number.
fn(state => {
  state.practitioner = {
    resourceType: 'Practitioner',
    meta: { profile: ['http://hl7.fr/ig/fhir/core/StructureDefinition/fr-core-practitioner'] },
    identifier: [
      {
        system: 'urn:oid:1.2.250.1.71.4.2.1', // idNatPS (RPPS-based)
        value: `8${state.data.rpps}`,
      },
    ],
    name: [{ family: state.data.nom, given: [state.data.prenom], prefix: ['Dr'] }],
  };
  return state;
});

Build Transaction Bundle.code:
// Wrap mapped resources in a transaction Bundle: PUT when the resource has an id, otherwise POST to create it.
fn(state => {
  const resources = [state.patient, state.practitioner];
  state.bundle = {
    resourceType: 'Bundle',
    type: 'transaction',
    entry: resources.map(r => ({
      resource: r,
      request: r.id
        ? { method: 'PUT', url: `${r.resourceType}/${r.id}` }
        : { method: 'POST', url: r.resourceType },
    })),
  };
  return state;
});
